1590→// Resolves the agent from state.AgentType internally. Multiple calls are safe but
1591→// not free — callers should avoid redundant calls for performance.
1592→func prepareTranscriptForState(ctx context.Context, state *SessionState) {
1593→	if !state.Phase.IsActive() || state.TranscriptPath == "" || state.AgentType == "" {
1594→		return
1595→	}
1596→	ag, err := agent.GetByAgentType(state.AgentType)
1597→	if err != nil {
1598→		logging.Debug(ctx, "prepareTranscriptForState: unknown agent type",
1599→			slog.String("session_id", state.SessionID),
1600→			slog.String("agent_type", string(state.AgentType)),
1601→			slog.Any("error", err),
1602→		)
1603→		return
1604→	}
1605→	prepareTranscriptIfNeeded(ctx, ag, state.TranscriptPath)
1606→}
1607→
1608→// prepareTranscriptIfNeeded calls PrepareTranscript for agents that implement
1609→// the TranscriptPreparer interface. This ensures transcript files exist before
1610→// they are read (e.g., OpenCode creates its transcript lazily via `opencode export`).
1611→// Errors are silently ignored — this is best-effort for hook paths.
1612→func prepareTranscriptIfNeeded(ctx context.Context, ag agent.Agent, transcriptPath string) {
